  }

  let payload: CreateProjectInput;
  try {
    const body = await request.json();
    payload = createProjectSchema.parse(body);
  } catch (error) {
    const message = error instanceof z.ZodError ? error.issues.map((issue) => issue.message).join(', ') : 'Invalid JSON body';
